import{_ as a}from"./chunks/mcp_setup_window.Bmk85iqH.js";import{_ as o,C as r,o as i,c as n,E as l,a2 as p}from"./chunks/framework.BEADHO7-.js";const A=JSON.parse('{"title":"AIに演出づくりを任せる","description":"ClaudeやCodexなどのAIが、Mug Typographyの使い方とLuaスクリプティング APIを自分で調べ、スクリプトを書いて動作まで確かめてくれるMCPサーバー","frontmatter":{"title":"AIに演出づくりを任せる","description":"ClaudeやCodexなどのAIが、Mug Typographyの使い方とLuaスクリプティング APIを自分で調べ、スクリプトを書いて動作まで確かめてくれるMCPサーバー","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-mcp.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"AIに演出づくりを任せる | Mug Typography Manual"}],["meta",{"property":"og:description","content":"ClaudeやCodexなどのAIが、Mug Typographyの使い方とLuaスクリプティング APIを自分で調べ、スクリプトを書いて動作まで確かめてくれるMCPサーバー"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-mcp.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"AIに演出づくりを任せる | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"ClaudeやCodexなどのAIが、Mug Typographyの使い方とLuaスクリプティング APIを自分で調べ、スクリプトを書いて動作まで確かめてくれるMCPサーバー"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"features/feature-mcp.md","filePath":"features/feature-mcp.md"}'),g={name:"features/feature-mcp.md"};function s(u,e,c,h,m,d){const t=r("FeatureHero");return i(),n("div",null,[l(t,{eyebrow:"MUG TYPOGRAPHY MCP",title:"AIに、演出づくりを任せる",description:"ClaudeやCodexなどのAIが、Mug Typographyの使い方とLuaスクリプティング APIを自分で調べ、スクリプトを書いて動作まで確かめてくれます。仕様書を貼り付ける手間がなくなり、エラーになるコードを受け取る場面も減ります。",image:"/image/mcp_hero_ja.svg","image-alt":"AIクライアントがMug Typography MCPで仕様を調べ、スクリプトを確かめて、DaVinci Resolveに演出を入れる流れの図","detail-link":"/features/feature-scripting","detail-label":"Luaスクリプティングの解説","point-one":"AIが仕様を自分で調べる","point-two":"書いたスクリプトの動作も確認","point-three":"6つのAIクライアントに対応","is-new":!0}),e[0]||(e[0]=p('<h2 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h2><ol><li><p>プラグイン本体と同じ<a href="https://muglab3.booth.pm/items/8339678" target="_blank" rel="noreferrer">BOOTHの商品ページ</a>から、お使いのOSのインストーラーをダウンロードして実行します。</p><ul><li>Windows: <code>MugTypographyMCP-Setup.exe</code></li><li>macOS: <code>MugTypographyMCP.pkg</code></li></ul><p>インストールが終わると、見つかったAIクライアントへ自動で登録されます。</p></li><li><p>インストーラーを開くときに、OSのセキュリティ警告が表示されることがあります。表示されたら、次のように進めてください。</p><ul><li><strong>Windows</strong>: 「Windows によって PC が保護されました」と表示されたら、<strong>詳細情報</strong>を押して、現れる<strong>実行</strong>を選びます。</li><li><strong>macOS</strong>: 「検証できません」などと表示されたら、メッセージを閉じて、「システム設定 &gt; プライバシーとセキュリティ」を開きます。下へスクロールして、<code>MugTypographyMCP.pkg</code>の横にある<strong>このまま開く</strong>を押します。パッケージをControlキーを押しながらクリックして、<strong>開く</strong>を選ぶ方法でも開けます。</li></ul></li><li><p>AIクライアントを再起動するか、MCPサーバーを再読み込みします。</p></li><li><p>作りたい演出を、AIに頼みます。</p><blockquote><p>Mug Typographyで「HELLO」の文字が1文字ずつ上から落ちてくる演出を作って、現在のタイムラインに追加して</p></blockquote></li></ol><h2 id="できること" tabindex="-1">できること <a class="header-anchor" href="#できること" aria-label="Permalink to &quot;できること&quot;">​</a></h2><p><strong>Mug Typography MCP</strong>を入れると、AIクライアントがMug Typographyについて必要なことを自分で調べ、書いたスクリプトを確かめられるようになります。</p><ul><li><strong>仕様を調べる</strong>: プラグインの機能、Inspectorのパラメーター、Luaスクリプティング API、同梱のサンプルを、AIが必要なときに読み取ります。仕様書を毎回貼り付けて読み込ませる必要はありません。</li><li><strong>フォント名を解決する</strong>: プラグインで選べるフォントの一覧をAIに伝えるので、日本語の表示名でフォントを指定できます。</li><li><strong>書いたスクリプトを確かめる</strong>: AIが書いたLuaスクリプトをシミュレーターで実行し、エラー、画面外に出る文字、値の変化を確かめます。1フレームのプレビュー画像も作ります。</li></ul><p>プレビュー画像は配置の目安です。仕上がりは必ずDaVinci Resolve上で確認してください。</p><h2 id="davinci-resolveの操作について" tabindex="-1">DaVinci Resolveの操作について <a class="header-anchor" href="#davinci-resolveの操作について" aria-label="Permalink to &quot;DaVinci Resolveの操作について&quot;">​</a></h2><p>Mug Typography MCP自体は、DaVinci Resolveを操作しません。ノードの追加や<strong>Script Text</strong>への設定までAIに任せたいときは、DaVinci Resolve用のMCPも、AIクライアントに組み合わせてください。スクリプトを作るだけなら、Resolve用のMCPは要りません。</p><h2 id="動作環境" tabindex="-1">動作環境 <a class="header-anchor" href="#動作環境" aria-label="Permalink to &quot;動作環境&quot;">​</a></h2><ul><li>Windows 11（64ビット）、またはmacOS 13.3以降（Apple Siliconのみ）</li><li>Mug Typographyをインストールした DaVinci Resolve Studio 21.1以降</li><li>次のいずれかのAIクライアント：Claude Desktop、Codex、Cursor、VS Code（GitHub Copilot）、Gemini CLI、Antigravity</li></ul><h2 id="登録状態の確認と解除" tabindex="-1">登録状態の確認と解除 <a class="header-anchor" href="#登録状態の確認と解除" aria-label="Permalink to &quot;登録状態の確認と解除&quot;">​</a></h2><p><img src="'+a+'" alt="Mug Typography MCPの設定画面。見つかった6つのAIクライアントがすべて登録済みと表示されている"></p><p>登録の状態は、次の画面で確認できます。</p><ul><li>Windows: スタートメニューの「Mug Typography MCP」</li><li>macOS: <code>~/Applications</code>の<code>MugTypographyMCP</code></li></ul><p>画面には、見つかったAIクライアントごとの状態が表示されます。<strong>Register all</strong>でまとめて登録、<strong>Unregister all</strong>でまとめて解除できます。<strong>Check the connection</strong>を押すと、全ツールを一度ずつ呼び出して、AIが送る内容と返ってくる内容を確かめられます。</p><h2 id="更新とアンインストール" tabindex="-1">更新とアンインストール <a class="header-anchor" href="#更新とアンインストール" aria-label="Permalink to &quot;更新とアンインストール&quot;">​</a></h2><ul><li><strong>更新</strong>: 新しいインストーラーを実行します。プログラムと登録が置き換わります。</li><li><strong>アンインストール</strong>: <ul><li>Windows: スタートメニューの「Uninstall Mug Typography MCP」か、「設定 &gt; アプリ」から行います。AIクライアントへの登録も解除されます。</li><li>macOS: <code>MugTypographyMCP</code>を開いて<strong>Unregister all</strong>で登録を解除してから、<code>~/Applications/MugTypographyMCP.app</code>をゴミ箱に入れます。</li></ul></li></ul><h2 id="うまくいかないときは" tabindex="-1">うまくいかないときは <a class="header-anchor" href="#うまくいかないときは" aria-label="Permalink to &quot;うまくいかないときは&quot;">​</a></h2><ul><li><strong>AIがMug Typographyの機能を使わない</strong> — AIクライアントを再起動するか、MCPサーバーを再読み込みしてください。設定画面の<strong>Check the connection</strong>で、AIから呼び出せているかも確かめられます。</li><li><strong>設定画面に「Another copy」と表示される</strong> — 以前に別の場所へ入れたものが、AIクライアントに登録されている状態です。<strong>Register all</strong>を押すと、今のものに置き換わります。</li></ul>',19))])}const C=o(g,[["render",s]]);export{A as __pageData,C as default};
